import numpy as np

def correlated_mutate(parent, mutation_rate, rng):
    child = parent.copy()
    if rng.random() < mutation_rate:
        child = 1 - child
    return child

def independent_mutate(parent, mutation_rate, rng):
    child = parent.copy()
    for i in range(len(child)):
        if rng.random() < mutation_rate:
            child[i] = 1 - child[i]
    return child

parent = np.array([1, 0, 1, 0])
rng = np.random.default_rng(7)
correlated_counts = [np.sum(correlated_mutate(parent, 0.3, rng) != parent) for _ in range(2000)]
independent_counts = [np.sum(independent_mutate(parent, 0.3, rng) != parent) for _ in range(2000)]

assert set(correlated_counts) <= {0, len(parent)}
assert any(count in {1, 2, 3} for count in independent_counts)
print("Correlated flip counts:", sorted(set(correlated_counts)))
print("Independent flip counts:", sorted(set(independent_counts)))
